"""Algorithm 2: exact separated outcome-block counts and the wall locator."""

from __future__ import annotations

import math
from dataclasses import dataclass
from typing import List, Optional, Tuple


def stage1_scalar(B: int) -> int:
    """k(B) = lcm(1..B), built from the powersmooth schedule."""
    if B < 2:
        return 1
    sieve = bytearray([1]) * (B + 1)
    sieve[0] = sieve[1] = 0
    for i in range(2, int(B**0.5) + 1):
        if sieve[i]:
            sieve[i * i :: i] = bytearray(len(sieve[i * i :: i]))
    k = 1
    for ell in (i for i in range(2, B + 1) if sieve[i]):
        pe = ell
        while pe * ell <= B:
            pe *= ell
        k *= pe
    return k


@dataclass(frozen=True)
class Blocks:
    """Exact cardinalities of the four separated outcome blocks."""

    dead: int
    found_p: int
    found_q: int
    nothing: int

    @property
    def total(self) -> int:
        return self.dead + self.found_p + self.found_q + self.nothing

    @property
    def reveal(self) -> int:
        return self.found_p + self.found_q


def exact_blocks(mp: int, mq: int, B: int) -> Blocks:
    """Exact block counts over the m_p * m_q trials of the two-prime cyclic model.

    With g_p = gcd(m_p, k(B)) and g_q = gcd(m_q, k(B)):
        dead = g_p g_q,  found_p = g_p (m_q - g_q),
        found_q = (m_p - g_p) g_q,  nothing = (m_p - g_p)(m_q - g_q).
    Exact: no sampling, no Monte Carlo error.  Cost: two gcds on Theta(B)-bit ints.
    """
    k = stage1_scalar(B)
    gp, gq = math.gcd(mp, k), math.gcd(mq, k)
    return Blocks(gp * gq, gp * (mq - gq), (mp - gp) * gq, (mp - gp) * (mq - gq))


def expected_curves(m: int, B: int) -> float:
    """E[T] = m / gcd(m, k(B)) <= m: finite at every bound, antitone in B."""
    return m / math.gcd(m, stage1_scalar(B))


def locate_walls(mp: int, mq: int, Bmax: int) -> Tuple[Optional[int], List[int]]:
    """Scan bounds 1..Bmax and locate (i) the least bound at which the reveal
    count vanishes -- the REAL wall, which sits at max of the two orders -- and
    (ii) every bound at which the found_p channel alone decreases (channel
    migration, the source of phantom walls)."""
    real_wall: Optional[int] = None
    migrations: List[int] = []
    prev_fp = None
    for B in range(1, Bmax + 1):
        b = exact_blocks(mp, mq, B)
        if real_wall is None and b.reveal == 0 and B > 1:
            real_wall = B
        if prev_fp is not None and b.found_p < prev_fp:
            migrations.append(B)
        prev_fp = b.found_p
    return real_wall, migrations


if __name__ == "__main__":
    assert exact_blocks(4, 6, 2).found_p == 8 and exact_blocks(4, 6, 3).found_p == 0
    assert exact_blocks(2, 2, 1).reveal == 2 and exact_blocks(2, 2, 2).reveal == 0
    b = exact_blocks(12, 1009, 20)
    assert b.total == 12 * 1009
    print("real wall / migrations for (m_p, m_q) = (4, 6):", locate_walls(4, 6, 12))
    print("real wall / migrations for (m_p, m_q) = (12, 1009):", locate_walls(12, 1009, 40))
